import{_ as t,c as i,o as n,a9 as r}from"./chunks/framework.C3PHgg-M.js";const c=JSON.parse('{"title":"Enterprise Interoperability","description":"Provider-neutral contracts for schedules, events, queues, long-running jobs, agents, and exports.","frontmatter":{"title":"Enterprise Interoperability","description":"Provider-neutral contracts for schedules, events, queues, long-running jobs, agents, and exports.","order":610000},"headers":[],"relativePath":"handbook/6_integrations/enterprise_interoperability/index.md","filePath":"handbook/6_integrations/enterprise_interoperability/index.md","lastUpdated":1778094759000}'),s={name:"handbook/6_integrations/enterprise_interoperability/index.md"};function a(l,e,o,u,p,d){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="enterprise-interoperability" tabindex="-1">Enterprise Interoperability <a class="header-anchor" href="#enterprise-interoperability" aria-label="Permalink to “Enterprise Interoperability”">​</a></h1><p>PURISTA enterprise interoperability is about making service contracts legible to schedulers, brokers, gateways, operators, and other platforms without moving business ownership out of PURISTA services.</p><p>The recommended long-running backend storyline is:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>schedule -&gt; event -&gt; event-to-queue binding -&gt; long-running queue -&gt; result event -&gt; subscription</span></span></code></pre></div><p>This keeps each responsibility small:</p><ul><li>schedules declare when something should happen, but production scheduling stays external</li><li>events publish business facts that can have many consumers</li><li>event-to-queue bindings perform bounded handoff from event delivery to durable work</li><li>queues own lease, retry, heartbeat, and dead-letter behavior</li><li>result events publish final worker output to downstream subscribers</li></ul><p>See the local runnable example in <code>examples/enterprise-billing-cycle</code>.</p><p>Continue with:</p><ul><li><a href="./scheduling.html">Scheduling</a></li><li><a href="./event-to-queue.html">Event-to-queue</a></li><li><a href="./long-running-queues.html">Long-running queues</a></li><li><a href="./result-events.html">Result events</a></li><li><a href="./async-agent-queues.html">Async agent queues</a></li><li><a href="./exports.html">Exports</a></li></ul>',9)])])}const g=t(s,[["render",a]]);export{c as __pageData,g as default};
